files.content:
body {
  min-height: 100vh;
  margin: 0;
  background-color: #396083;
}

.gallery {
  display: flex;
  justify-content: space-between;
  width: 650px;
  height: 400px;
}

.gallery__column_type_left {
  width: 255px;
}

.gallery__column_type_right {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  width: 385px;
}

.gallery__column img {
  object-fit: cover;
  object-position: center;
}

.gallery__column_type_left img {
  width: 100%;
  height: 100%;
}

.gallery__column_type_right img {
  width: 100%;
  height: 195px;
}
